    const P = (x, y) => [(x - 883) * 0.1 * k, (340 - y) * 0.1 * k + yH];
    const wave = sideExtrude(refShape([['m', 588, 325], ['c', 640, 300, 720, 288, 800, 288], ['c', 860, 288, 900, 300, 940, 303],
      ['l', 968, 305], ['q', 982, 306, 981, 318], ['l', 981, 326], ['q', 980, 337, 965, 337], ['l', 948, 339],
      ['c', 900, 341, 860, 341, 800, 339], ['c', 720, 336, 650, 340, 606, 358], ['q', 596, 363, 593, 353], ['l', 588, 325]], P), m.actW, lo);
    const [tx, ty] = P(591, 340), dir = new THREE.Vector3(-0.96, -0.28, 0).normalize();
