    const col = cyl(r, yc - 0.3, m.actH + 0.3, 0.8, 0, lo), pa = col.attributes.position;
    for (let i = 0; i < pa.count; i++) pa.setY(i, pa.getY(i) + (pa.getY(i) - yc) / m.actH * -pa.getX(i) * slope);
    col.computeVertexNormals(); head.push(col);
