const sceneOf = () => { const sc = { ...SCENE0, ...(S.scene || {}) }; if (sc.cena === 'pedra') sc.cena = 'nenhum'; return sc; }; // pedra saiu
// Produto inclinado no cenário: gira em volta do centro da base.
