    for (let i = 0; i <= 24; i++) { const a = i / 24 * Math.PI / 2; prof.push([zb - R * Math.sin(a), R - R * Math.cos(a)]); }
    for (let y = R + 20; y <= 1400; y += 40) prof.push([zb - R, y]);
