const unpackJSON = js => JSON.parse(js, (k, v) => typeof v === 'string' && v.startsWith(BIG_TAG) ? BIG_BACK.get(+v.slice(BIG_TAG.length)) ?? '' : v);
function record() {
  if (restoring) return;
  const cur = packJSON(S), now = performance.now();
  if (hist[hi] === cur) return;
  if (hi > 0 && now - lastRec < 600 && hist.length - 1 === hi && hi === coalesceFrom) hist[hi] = cur;
  else { hist = hist.slice(0, hi + 1); hist.push(cur); hi = hist.length - 1; coalesceFrom = hi; if (hist.length > 100) { hist.shift(); hi--; coalesceFrom = hi; } }
  lastRec = now; updateUndoBtns();
}
let coalesceFrom = -1;
function restore(json) {
  restoring = true;
  S = normalize(unpackJSON(json)); sel = clamp(sel, 0, S.modules.length - 1);
  renderAll(); build();
  restoring = false; coalesceFrom = -1; updateUndoBtns();
}
function undo() { if (hi > 0) { hi--; restore(hist[hi]); toast('Desfeito'); } }
function redo() { if (hi < hist.length - 1) { hi++; restore(hist[hi]); toast('Refeito'); } }
function updateUndoBtns() {
  const u = $('#undoBtn'), r = $('#redoBtn'); if (!u) return;
  u.disabled = hi <= 0; r.disabled = hi >= hist.length - 1;
  u.style.opacity = u.disabled ? 0.4 : 1; r.style.opacity = r.disabled ? 0.4 : 1;
}

// Monta as peças de um modelo num grupo (cena principal ou miniatura).
