  out.push(`<g id="VINCO"><path d="${segs(G.crease)}" fill="none" stroke="#0057b8" stroke-width="0.25" stroke-dasharray="2 1.2"/></g>`);
  out.push(`<g id="TEXTO">${G.labels.map(([x, y, t, sz]) => txt(x + ox, y + oy, t, sz, 'middle', '#9a9a9a')).join('')}</g>`);
