    const D = [dim(cx0 + ox, by, cx1 + ox, by, `${r1(cx1 - cx0)} mm`), dim(cx1 + ox + 7, cy0 + oy, cx1 + ox + 7, cy1 + oy, `${r1(cy1 - cy0)} mm`, true)];
