    const lg = (x, color, dash, label) => `<path d="M${f(x)} ${fr + 6} h9" stroke="${color}" stroke-width="0.6"${dash ? ` stroke-dasharray="${dash}"` : ''}/>` + txt(x + 11, fr + 7.1, label, 3, 'start', ink, 700);
