  const sz = b.getSize(new THREE.Vector3()), c = b.getCenter(new THREE.Vector3());
  const dir = new THREE.Vector3(...VIEWS[viewName]).normalize();
  const aspect = view.clientWidth / Math.max(view.clientHeight, 1);
