function renderWallFields() {
  const vf = $('#volFields'); if (!vf) return; vf.innerHTML = '';
  field(vf, S, ['wallAuto', `Parede automática pelo material (vidro ${WALL_AUTO.vidro} · PET ${WALL_AUTO.pet} · plástico ${WALL_AUTO.plast} mm)`, 'check'], () => { applyAutoWall(); renderEditorKeepScroll?.(); renderAll(); queueBuild(); });
  field(vf, S, ['wall', 'Espessura da parede', 0.3, 4, 0.1, 'mm'], () => { S.wallAuto = false; queueBuild(); }); // mexeu no número: vale o seu
  const b = S.modules.find(v => v.vol); if (!b) return;
  const glass = thickBase(b.own ? b.finish : S.finish, b);
  const el = field(vf, b, ['fundo', 'Espessura do fundo (vidro: massa embaixo)', 1, 25, 0.5, 'mm', null, 6], queueBuild);
  if (!glass) { el.classList.add('off'); el.title = 'Só no vidro: no plástico o fundo tem a espessura da parede'; }
}
function renderGlobal() {
  const vf = $('#volFields'); vf.innerHTML = '';
  renderWallFields();
  const lf = $('#lookFields'); lf.innerHTML = '';
  field(lf, S, ['color', 'Cor geral', 'color'], () => { renderStack(); queueBuild(); });
  field(lf, S, ['finish', 'Acabamento geral', 'finish'], () => { delete S.difus; delete S.ior; renderGlobal(); queueBuild(); });
  field(lf, S, ['difus', 'Difusão (0 = liso/polido, 100 = bem difuso)', 0, 100, 1, '%', null, o => presetDif(o.finish)], queueBuild);
  if (isGlass(S.finish)) field(lf, S, ['ior', 'IOR do vidro (1,0 ar · 1,33 água · 1,5 vidro · 2,4 diamante)', 1, 2.4, 0.01, '', null, o => presetIor(o.finish)], queueBuild);
  matRow(lf, () => { const m = S.modules[sel]; return m?.own ? m : S; }, d => { renderGlobal(); renderEditorKeepScroll(); if (d) { renderStack(); queueBuild(); } });
  $('#projName').value = fileName();
}

// ───────────────────────── painéis: abas, menus e inspetor ─────────────────────────
// Topo: arquivo, desfazer, busca (Cmd/Ctrl+K) e Exportar. Barra de ícones à esquerda com os modos:
// Modelos, Peças, Linha (lado a lado), Medidas (volume e referência) e Cena. Direita: a peça
// selecionada em abas (Forma, Detalhes, Superfície = cor/acabamento/conteúdo, Logo e rótulo).
const appEl = document.querySelector('.app');
// Dica curta no topo de cada aba, na primeira vez (o ✕ guarda que já viu).
const HINTS = {
  lib: 'Comece do zero, pelo gerador, por um desenho ou STL, ou abra um modelo pronto ou salvo (arraste um modelo para a cena para colocar ao lado).',
  build: 'Clique numa peça (aqui ou no 3D) e os controles da forma abrem à direita. A bolinha colorida abre a cor da peça. Botão direito numa peça no 3D: atalhos (trocar, cor, duplicar, excluir).',
  color: 'Escolha se a cor vale só para a peça ou para o produto inteiro. Salve materiais (ex.: vidro verde fosco) para reusar.',
  scene: 'Luz, fundo e cenário valem para a tela, o PNG e o vídeo. Salve a luz em "Minhas luzes" para reusar.',
};
function placeHints() {
  const seen = store.get('shape.hintsSeen', {});
  document.querySelectorAll('aside > .tab').forEach(t => {
    const k = t.dataset.t; t.querySelector(':scope > .hint')?.remove(); if (!HINTS[k] || seen[k]) return;
    const h = document.createElement('div'); h.className = 'hint'; h.textContent = HINTS[k];
    const x = document.createElement('button'); x.textContent = '✕'; x.title = 'Entendi'; x.onclick = () => { const s = store.get('shape.hintsSeen', {}); s[k] = true; store.set('shape.hintsSeen', s); h.remove(); };
    h.appendChild(x); const ttl = t.querySelector(':scope > .tabTitle'); if (ttl) ttl.after(h); else t.prepend(h);
  });
}
placeHints();
// Criar: atalhos para as formas de começar um produto.
