// Biblioteca de módulos
// Corpo, tampa e peça de encaixe ficam em listas separadas.
const CATS = [
  ['Corpo', ['reto', 'boston', 'quadrado', 'capsula', 'perfumeOval', 'plano', 'arco', 'cone', 'placa', 'bisnaga', ...DRAFT_KEYS.corpo]],
  ['Tampa', ['incomSens', 'incomTambor', 'incomBola', 'incomColarBola', 'incomDiscTop', 'incomFlipTop', 'incomCapaMist', 'incomCapaMistBig', 'esfera', 'esferaBisnaga', 'nuvem', 'taca', 'domo', 'seixo', 'flip', 'flipRedondo', 'flipAba', 'disctop', 'sobretampa', 'tampaBisnaga', 'tampaSextavada', 'disco']],
  ['Válvula', ['patoIncom', 'incomSpray', 'incomDosadora', 'incomEspumadora', 'incomTrigger', 'incomBicoAplicador', 'pump', 'pumpFrisos', 'locao', 'espuma', 'pumpDosadora', 'spray', 'sprayClassico', 'contaGotas', 'tampaGloss', 'pushPull', 'pushSport', 'bicoDosador', 'bicoConico', 'lamina', 'pumpOnda', 'gatilho', 'pumpBisnaga']],
  ['Peça de encaixe', ['gargalo', 'colar', 'barril', 'flare', 'anel', 'tigela', 'bola', 'sextavado', 'canelado']],
];
function partOriginGroups(label, keys) {
  return ['Incom', 'Outbox / genérico'].map(origin => [
    `${origin} · ${label}`, keys.filter(k => (LIB[k].forn === 'Incom' ? 'Incom' : 'Outbox / genérico') === origin)
  ]).filter(([, ks]) => ks.length);
}
function renderAddParts() {
$('#addRows').replaceChildren();
CATS.forEach(([label, keys]) => {
  const row = document.createElement('div'); row.className = 'row';
  row.innerHTML = `<select>${partOriginGroups(label, keys.filter(k => k !== 'gargalo')).map(([title, ks]) => `<optgroup label="${title}">${ks.map(k => `<option value="${k}">${LIB[k].name}</option>`).join('')}</optgroup>`).join('')}</select>
    <button class="btn pri sm" style="flex:0;min-width:118px">+ ${label}</button>`;
  row.querySelector('button').onclick = () => {
    const at = sel + unitLen(sel);
    S.modules.splice(at, 0, M(row.querySelector('select').value));
    sel = at; renderStack(); renderEditor(); build();
  };
  $('#addRows').appendChild(row);
});
}
renderAddParts();
$('#stlGalBtn').onclick = () => $('#importStl').click(); // único botão de subir STL (ao lado de Salvar)
// Põe um STL no produto como peça (logo acima da selecionada). Low-poly já entra com a
// malha melhorada (dá para desligar em "Melhorar malha").
function addStlModule(buf, name) {
  const geo = stlLoader.parse(buf); geo.computeBoundingBox();
  const b = geo.boundingBox, W = r1(Math.max(1, b.max.x - b.min.x)), h = r1(Math.max(1, b.max.y - b.min.y)), D = r1(Math.max(1, b.max.z - b.min.z));
  const low = stlIsLowPoly(geo); geo.dispose?.();
  const at = sel + unitLen(sel), m = { ...BASE, uid: newUid(), type: 'stl', kind: 'mesh', name, W, D, h, meshData: bytesToB64(buf), meshRotX: 0, meshRotY: 0, meshRotZ: 0, meshSmooth: false,
    own: true, color: S.color || BEIGE, finish: S.finish || 'fosco', vol: false, pesc: false, bpesc: false };
  S.modules.splice(at, 0, m);
  sel = at; renderStack(); renderEditor(); build(); fit();
  return { m, low };
}
// Uploads da equipe (api/uploads.php): STL guardado no banco, com miniatura, para reusar
// em qualquer projeto pela aba "Uploads" da galeria.
let stlUploads = []; // [{ id, name, size, thumb }]
async function refreshStlUploads() {
  if (!cloud) return;
  try { stlUploads = (await api('uploads.php?a=list&kind=stl')).files || []; galleryKey = ''; renderPresets(); } catch {}
}
function stlThumb(m) { // miniatura da peça sozinha (mesmo desenho da galeria)
  try { return Promise.resolve(thumbOf({ color: m.color, finish: m.finish, modules: [{ ...m, own: false }] }) || ''); } catch { return Promise.resolve(''); }
}
// Envio genérico em pedaços para a biblioteca da equipe (uploads.php).
async function uploadTeamFile(kind, bytes, name, thumb) {
  const CH = 768 * 1024, n = Math.ceil(bytes.length / CH);
  const b64 = u8 => { let s = ''; for (let i = 0; i < u8.length; i += 32768) s += String.fromCharCode.apply(null, u8.subarray(i, i + 32768)); return btoa(s); };
  const { id } = await api('uploads.php?a=start', { kind, name, size: bytes.length, chunks: n, thumb });
  for (let i = 0; i < n; i++) { await api('uploads.php?a=chunk', { id, i, data: b64(bytes.subarray(i * CH, (i + 1) * CH)) }); if (n > 2) toast(`Guardando ${name}… ${Math.round((i + 1) / n * 100)}%`); }
  await api('uploads.php?a=finish', { id });
}
