  const ov = document.createElement('div'); ov.className = 'openDlg';
  ov.innerHTML = `<div class="openBox"><div class="openHead"><b>Abrir projeto</b><input type="search" placeholder="Procurar pelo nome…"><button class="btn sm">Fechar</button></div><div class="openGrid"></div></div>`;
