          try {
            if (cloud) { await api('models.php?a=delete', { name: it.name }); delete cloud[it.name]; cloudList = cloudList.filter(x => x.name !== it.name); }
            else { const sv = store.get('shape.presets', {}); delete sv[it.name]; store.set('shape.presets', sv); }
          } catch (er) { return toast(er.status === 401 ? 'Sua sessão expirou: entre de novo' : 'Não consegui excluir'); }
