        c.querySelector('div').textContent = it.name;
        c.querySelector('small').textContent = it.updated ? new Date(it.updated.replace(' ', 'T')).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '';
