// Projeto que usa um HDR da equipe: baixa do servidor quando a luz pede
async function ensureHdr(name) {
  if (name?.startsWith('ph:')) {
    if (HDR.name === name || hdrLoading === name) return;
    hdrLoading = name; toast(`Carregando luz ${phLabel(name)}…`);
    try {
      const r = await fetch(phHdrUrl(name.slice(3))); if (!r.ok) throw 0;
      if (await loadHdr(await r.blob(), name) && sceneOf().hdrName === name) { renderScene(); applySceneLight(); req(); }
    } catch { toast('Não consegui baixar essa luz (precisa de internet)'); } finally { hdrLoading = ''; }
    return;
  }
  if (!name || HDR.name === name || hdrLoading === name || !cloud) return;
  hdrLoading = name;
  try {
    if (!hdrFiles) { const { files } = await api('hdr.php?a=list'); hdrFiles = Object.fromEntries(files.map(f => [f.name, f.id])); hdrNames = files.map(f => f.name); }
    const id = hdrFiles[name]; if (!id) return;
    const r = await fetch(`api/hdr.php?a=file&id=${id}`, { credentials: 'same-origin' }); if (!r.ok) return;
    if (await loadHdr(await r.blob(), name) && sceneOf().hdrName === name) { renderScene(); applySceneLight(); req(); }
  } catch {} finally { hdrLoading = ''; }
}
$('#hdrFile').onchange = async e => {
  const f = e.target.files[0]; if (!f) return; e.target.value = '';
  if (!(await loadHdr(f, f.name))) return;
  S.scene = { ...sceneOf(), luz: 'hdr', hdrName: f.name }; renderScene(); applySceneLight(); saveLocalSoon(); req(); // HDR carregado vira a luz da cena
  const kind = /\.exr$/i.test(f.name) ? 'EXR' : 'HDR';
  if (!cloud) return toast(`${kind} carregado (entre na conta para guardar no servidor)`);
  try { await uploadHdr(f, f.name); toast(`${kind} guardado para a equipe: ${f.name}`); }
  catch (err) { toast(err.code === 'size' ? `${kind} grande demais (máx. 150 MB)` : `${kind} carregado, mas não consegui guardar no servidor`); }
};

