// Login e modelos ficam no PHP + MySQL da Hostinger (pasta api/). Servido sem PHP
// (ex.: python -m http.server) o OUTBOX abre direto e salva só no navegador.
async function api(path, body) {
  const r = await fetch('api/' + path, body === undefined ? { cache: 'no-store', credentials: 'same-origin' }
    : { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  let j = null; try { j = await r.json(); } catch {}
  if (!j) { const e = new Error('sem api'); e.noApi = r.ok || r.status === 404; e.status = r.status; throw e; }
  if (!r.ok) { const e = new Error(j.error || 'erro'); e.code = j.error; e.status = r.status; throw e; }
  return j;
}
const loginUI = {
  set(title, btn, { note = '', pass2 = false, email = null } = {}) {
    $('#loginTitle').textContent = title; $('#loginBtn').textContent = btn; $('#loginNote').textContent = note;
    $('#loginPass2').classList.toggle('hidden', !pass2); $('#forgotBtn').classList.toggle('hidden', pass2);
    $('#loginPass').autocomplete = pass2 ? 'new-password' : 'current-password';
    $('#loginPass').placeholder = pass2 ? 'Nova senha (mín. 8 caracteres)' : 'Senha';
    $('#loginUser').readOnly = email !== null; if (email !== null) $('#loginUser').value = email;
    $('#loginError').textContent = '';
  },
  err(t) { $('#loginError').textContent = t; },
};
function loginForm() {
  loginUI.set('Acesso privado', 'Entrar');
  $('#loginForm').onsubmit = async e => {
    e.preventDefault(); loginUI.err('');
    try { signedIn((await api('auth.php?a=login', { email: $('#loginUser').value.trim(), password: $('#loginPass').value })).user); }
    catch (err) { loginUI.err(err.code === 'wait' ? 'Muitas tentativas. Tente de novo em 15 minutos.' : err.code === 'invalid' ? 'E-mail ou senha inválidos' : 'Não consegui entrar agora'); }
  };
}
$('#forgotBtn').onclick = () => { $('#loginNote').textContent = 'Peça a quem administra a equipe um novo link de senha.'; };
async function passwordForm(token) {
  let info;
  try { info = await api('auth.php?a=token&t=' + encodeURIComponent(token)); }
  catch { history.replaceState(null, '', location.pathname); loginForm(); return loginUI.err('Este link expirou ou já foi usado. Peça um novo.'); }
  loginUI.set('Criar senha', 'Salvar senha e entrar', { pass2: true, email: info.email });
  $('#loginForm').onsubmit = async e => {
    e.preventDefault();
    const p1 = $('#loginPass').value, p2 = $('#loginPass2').value;
    if (p1.length < 8) return loginUI.err('A senha precisa ter pelo menos 8 caracteres');
    if (p1 !== p2) return loginUI.err('As senhas não são iguais');
    try { const { user } = await api('auth.php?a=set_password', { token, password: p1 }); history.replaceState(null, '', location.pathname); signedIn(user); }
    catch { loginUI.err('Este link expirou ou já foi usado. Peça um novo.'); }
  };
}
let ME = null;
async function signedIn(user) {
  ME = user;
  unlock(); resize(); fit(curView);
  $('#build').textContent = `versão ${BUILD} · ${user.name || user.email}`;
  cloud = {};
  // Primeiro login neste navegador: leva os modelos salvos só aqui para a conta.
  const local = store.get('shape.presets', {}), flag = 'shape.imported.' + user.id;
  if (Object.keys(local).length && !store.get(flag, false)) {
    try { const { imported } = await api('models.php?a=import', { items: local }); store.set(flag, true); if (imported) toast(`${imported} modelo(s) deste navegador foram para a sua conta`); } catch {}
  }
  try { cloudList = (await api('models.php?a=list')).models || []; renderLineup(); } // só a lista (nome, data, miniatura)
  catch { toast('Não consegui carregar seus modelos'); }
  try { teamAba = (await api('settings.php?a=get&k=galAba')).value || {}; } catch { teamAba = null; } // abas da equipe
  refreshHdrList(); // HDR/EXR da equipe
  refreshStlUploads(); // STL da equipe (aba Uploads)
  refreshReliefLib(); // texturas de relevo da equipe
  refreshMatLib().then(() => { renderGlobal(); renderEditorKeepScroll(); }); // materiais da equipe
  galleryKey = ''; renderPresets();
  if (user.is_admin) { $('#teamBox').classList.remove('hidden'); renderTeam(); }
}
// Equipe: quem administra adiciona pessoas e gera o link para cada uma criar a senha.
async function renderTeam(link) {
  const box = $('#team'); box.innerHTML = '';
  const el = (tag, cls, text) => { const x = document.createElement(tag); if (cls) x.className = cls; if (text != null) x.textContent = text; return x; };
  if (link) {
    const url = location.origin + location.pathname + '?senha=' + link.token;
    const card = el('div', 'team-link'); card.append(el('div', 'tip', `Link para ${link.who} criar a senha (vale 7 dias, uma vez só):`));
    const inp = el('input'); inp.readOnly = true; inp.value = url; inp.onclick = () => inp.select();
    const cp = el('button', 'btn sm', 'Copiar link'); cp.onclick = async () => { try { await navigator.clipboard.writeText(url); toast('Link copiado'); } catch { inp.select(); } };
    card.append(inp, cp); box.append(card);
  }
  let users = [];
  try { users = (await api('team.php?a=list')).users; } catch { box.append(el('div', 'tip', 'Não consegui carregar a equipe')); return; }
  for (const u of users) {
    const row = el('div', 'team-row'), who = el('div', 'who', u.name || u.email);
    who.append(el('small', null, `${u.email}${u.is_admin ? ' · admin' : ''}${u.active ? '' : ' · aguardando senha'}`));
    const lk = el('button', 'btn sm', 'Link de senha');
    lk.onclick = async () => { try { renderTeam({ who: u.name || u.email, token: (await api('team.php?a=link', { id: u.id })).token }); } catch { toast('Não consegui gerar o link'); } };
    const rn = el('button', 'btn sm', 'Renomear');
    rn.onclick = async () => {
      const n = (prompt('Nome:', u.name || '') || '').trim(); if (!n || n === u.name) return;
      try { await api('team.php?a=rename', { id: u.id, name: n }); toast('Nome trocado');
        if (u.email === ME?.email) $('#build').textContent = `versão ${BUILD} · ${n}`;
        renderTeam(); } catch { toast('Não consegui trocar o nome'); }
    };
    const em = el('button', 'btn sm', 'E-mail');
    em.title = 'Trocar o e-mail de login (senha e modelos continuam)';
    em.onclick = async () => {
      const e = (prompt('Novo e-mail de login:', u.email) || '').trim().toLowerCase(); if (!e || e === u.email) return;
      try { await api('team.php?a=email', { id: u.id, email: e }); toast(`Login agora é ${e}`); if (u.email === ME?.email) ME.email = e; renderTeam(); }
      catch (er) { toast(er.code === 'exists' ? 'Esse e-mail já está na equipe' : er.code === 'email' ? 'E-mail inválido' : 'Não consegui trocar o e-mail'); }
    };
    row.append(who, rn, em, lk);
    if (!(u.is_admin && users.filter(x => x.is_admin).length === 1)) {
      const rm = el('button', 'btn sm', '✕'); rm.title = 'Remover da equipe';
      rm.onclick = async () => {
        if (!confirm(`Remover ${u.name || u.email}? Os modelos dessa pessoa serão apagados.`)) return;
        try { await api('team.php?a=remove', { id: u.id }); renderTeam(); } catch (e) { toast(e.code === 'self' ? 'Você não pode remover a própria conta' : 'Não consegui remover'); }
      };
      row.append(rm);
    }
    box.append(row);
  }
  const add = el('div', 'team-add'), nm = el('input'), em = el('input'), go = el('button', 'btn pri sm', '+ Pessoa');
  nm.placeholder = 'Nome'; em.placeholder = 'E-mail'; em.type = 'email';
  go.onclick = async () => {
    try { const { token } = await api('team.php?a=add', { name: nm.value.trim(), email: em.value.trim() }); renderTeam({ who: nm.value.trim() || em.value.trim(), token }); }
    catch (e) { toast(e.code === 'exists' ? 'Esse e-mail já está na equipe' : e.code === 'email' ? 'E-mail inválido' : 'Não consegui adicionar'); }
  };
  add.append(nm, em, go); box.append(el('div', 'tip', 'Adicionar pessoa:'), add);
}
try {
  const { user } = await api('auth.php?a=me');
  const token = new URLSearchParams(location.search).get('senha');
  if (token) passwordForm(token);
  else if (user) signedIn(user);
  else loginForm();
} catch (e) {
  if (e.noApi) { unlock(); resize(); fit(curView); $('#logoutBtn').classList.add('hidden'); } // sem PHP: modo local
  else { loginForm(); loginUI.err(e.code === 'config' ? 'O banco de dados ainda não foi configurado (api/config.php).' : 'O servidor não respondeu. Tente de novo.'); }
}
